  const { p, btn } = await withBooking();
  const n = p.calls.length;
  btn.dispatch('click');
  lastCall(p).reject();
  await p.flush();
  assert.equal(err(p), NO_REPLY);
  assert.equal(btn.disabled, false);
  assert.equal(p.calls.length, n + 1);
});

