// ---------- submit ----------
async function filled() {
  const p = await ready();
  p.el('title').value = '  hi  ';
  p.el('date').value = '2026-11-03';
  p.el('start').value = '09:00';
  p.el('end').value = '10:00';
  return p;
}

test('submit: preventDefault, disabled, POST payload, second submit ignored', async () => {
  const p = await filled();
  const n = p.calls.length;
  const ev = p.el('booking-form').dispatch('submit');
  assert.equal(ev.defaultPrevented, true);
  assert.equal(p.el('book').disabled, true);
  assert.equal(p.calls.length, n + 1);
  const c = lastCall(p);
  assert.equal(c.url, '/api/bookings');
  assert.equal(c.options.method, 'POST');
  assert.deepEqual(c.options.headers, { 'Content-Type': 'application/json' });
  assert.deepEqual(JSON.parse(c.options.body),
    { room: 'Aurora', title: '  hi  ', date: '2026-11-03', start: '09:00', end: '10:00' });
  const ev2 = p.el('booking-form').dispatch('submit');
  assert.equal(ev2.defaultPrevented, true);
  assert.equal(p.calls.length, n + 1);
});

test('submit: 201 enables, clears title only, clears error, refetches', async () => {
  const p = await filled();
  p.calls[0].resolve; // no-op reference
  p.el('error').textContent = 'old';
  const n = p.calls.length;
  p.el('booking-form').dispatch('submit');
  lastCall(p).resolve(201, { id: 1 });
  await p.flush();
  assert.equal(p.el('book').disabled, false);
  assert.equal(p.el('title').value, '');
  assert.equal(p.el('date').value, '2026-11-03');
  assert.equal(p.el('start').value, '09:00');
  assert.equal(p.el('end').value, '10:00');
  assert.equal(err(p), '');
  assert.equal(p.calls.length, n + 2);
  assert.equal(lastCall(p).url, '/api/bookings');
  assert.equal(lastCall(p).options.method, 'GET');
});

test('submit: 409 shows message, keeps title, no refetch', async () => {
  const p = await filled();
  const n = p.calls.length;
  p.el('booking-form').dispatch('submit');
  lastCall(p).resolve(409, { error: 'room is already booked from 09:00 to 10:00' });
  await p.flush();
  assert.equal(err(p), 'room is already booked from 09:00 to 10:00');
  assert.equal(p.el('title').value, '  hi  ');
  assert.equal(p.el('book').disabled, false);
  assert.equal(p.calls.length, n + 1);
});

test('submit: reject and bad json show no-reply, enable Book', async () => {
  for (const mode of ['reject', 'bad']) {
    const p = await filled();
    p.el('booking-form').dispatch('submit');
    if (mode === 'reject') lastCall(p).reject(); else lastCall(p).resolveBadJson(201);
    await p.flush();
    assert.equal(err(p), NO_REPLY, mode);
    assert.equal(p.el('book').disabled, false, mode);
    assert.equal(p.el('title').value, '  hi  ', mode);
  }
});

test('submit: Book stays disabled until json() settles', async () => {
  const p = await filled();
  p.el('booking-form').dispatch('submit');
  let release;
  const pending = new Promise((r) => { release = r; });
  lastCall(p).resolveWith({ status: 201, json: () => pending });
  await p.flush();
  assert.equal(p.el('book').disabled, true);
  release({ id: 1 });
  await p.flush();
  assert.equal(p.el('book').disabled, false);
});

